// LIN-3173: independent check of docs/papers/harbour/browser-flakes.md (LIN-3168). Recounts the paper's figures from the snapshots,
// mostly from the raw files (ci-runs.json, detail/, green/) rather than the author's analysis.json, and prints each check.
// Usage: node scripts/survey-check-5-flakes.mjs [--dir data/survey-flakes] [--analysis <analysis.json regenerated by survey-flakes-analyse.mjs>]
//        [--fresh <ci-runs.json from a fresh survey-tests-ci-runs.mjs>] [--gh]   (--gh: look up merged PRs' head branches, ~13 API calls)
// Read-only except for stdout; needs local git for the spec count at fe541ee9.
import { execFileSync } from 'child_process';
import { readFileSync, readdirSync, existsSync } from 'fs';
import { join } from 'path';

const argv = process.argv.slice(2);
const arg = (k, d) => { const i = argv.indexOf(k); return i >= 0 ? argv.splice(i, 2)[1] : d; };
const dir = arg('--dir', 'data/survey-flakes');
const analysisPath = arg('--analysis', join(dir, 'analysis.json'));
const freshPath = arg('--fresh', null);
const useGh = argv.includes('--gh');
const J = (p) => JSON.parse(readFileSync(p, 'utf8'));
const readDir = (d) => readdirSync(join(dir, d)).filter((f) => f.endsWith('.json')).map((f) => J(join(dir, d, f)));
const mins = (a, b) => (new Date(b) - new Date(a)) / 60000;
const pct = (a, b) => `${a}/${b} = ${(100 * a / b).toFixed(1)}%`;
const tally = (xs, f) => xs.reduce((m, x) => { const k = f(x); m[k] = (m[k] || 0) + 1; return m; }, {});
const median = (xs) => { const s = [...xs].sort((a, b) => a - b); const n = s.length; return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2; };
const ci95 = (p, n) => 1.96 * Math.sqrt(p * (1 - p) / n) * 100;
const h = (t) => console.log(`\n== ${t}`);

const runs = J(join(dir, 'ci-runs.json'));
const lv = runs.repos.LinearViewer.runs;
const A = J(analysisPath);
const census = A.census;
const flakes = census.filter((x) => x.class === 'flake');

h('Population and period table');
const period = (t) => (t < '2026-06-24' ? '1-23 Jun' : t < '2026-07-01' ? '24-30 Jun' : t.slice(0, 7));
console.log('LV runs', lv.length, 'SD runs', runs.repos['simple-dispatcher'].runs.length, 'PR runs', lv.filter((r) => r.event === 'pull_request').length);
console.log('runs per period', tally(lv, (r) => period(r.created_at)), 'flakes per period', tally(flakes, (x) => period(x.date)));
if (freshPath) {
  const F = J(freshPath); const cut = runs.fetchedAt;
  for (const repo of Object.keys(runs.repos)) {
    const a = new Set(runs.repos[repo].runs.map((r) => r.id)); const f = F.repos[repo].runs.filter((r) => r.created_at <= cut);
    const extra = f.filter((r) => !a.has(r.id));
    console.log(`fresh ${repo}: ${f.length} runs created before the author's fetch (author ${a.size}); extra`, extra.map((r) => `${r.id} ${r.created_at} ${r.event} ${r.conclusion}`));
    if (repo === 'LinearViewer') console.log('  fresh runs per period', tally(f, (r) => period(r.created_at)), 'PR runs', f.filter((r) => r.event === 'pull_request').length);
  }
}

h('Census classes');
console.log('attempts', census.length, tally(census, (x) => x.class));
console.log('"cannot be placed" = unverified + unresolved + main moved =', census.filter((x) => ['unverified', 'unresolved', 'main moved'].includes(x.class)).length);
console.log('attempts with no log', census.filter((x) => !x.log).length);
console.log('1-23 June E2E-red attempts:');
for (const x of census.filter((y) => y.date < '2026-06-24')) console.log(`  ${x.date.slice(0, 16)} ${x.runId}/${x.attempt} ${x.event} ${x.class} res=${x.resolution} sameShaGreen=${x.sameShaGreen} rerun=${x.rerun}`);
for (const x of census.filter((y) => y.class === 'environment')) {
  const d = J(join(dir, 'detail', `LinearViewer-${x.runId}-${x.attempt}.json`));
  console.log(`  environment ${x.runId}/${x.attempt}: failed steps`, d.jobs.filter((j) => /^E2E/.test(j.name)).flatMap((j) => j.steps.filter((s) => !['success', 'skipped'].includes(s.conclusion)).map((s) => `${j.name}: ${s.name} (${s.conclusion})`)));
}
console.log('24-30 June flake basis', tally(flakes.filter((x) => period(x.date) === '24-30 Jun'), (x) => `${x.basis} / ${x.rerun ? 'rerun' : 'new run'}`),
  'in', new Set(flakes.filter((x) => period(x.date) === '24-30 Jun').map((x) => x.runId)).size, 'runs');
console.log('main-moved rows', census.filter((x) => x.class === 'main moved').map((x) => `${x.date.slice(0, 10)} ${x.runId} ${x.tests[0] || '(no log)'}`));

h('Seven specs');
const bySpec = {};
for (const x of flakes) for (const s of x.specs) (bySpec[s.replace('tests/e2e/', '')] ||= []).push(x);
for (const [s, xs] of Object.entries(bySpec).sort((a, b) => b[1].length - a[1].length)) {
  const ds = xs.map((x) => x.date.slice(0, 10)).sort();
  console.log(`${s.padEnd(30)} ${xs.length} flakes in ${new Set(xs.map((x) => x.runId)).size} runs, ${ds[0]}..${ds.at(-1)}`, tally(xs, (x) => x.date.slice(0, 7)),
    'tests', Object.keys(tally(xs.flatMap((x) => x.tests), (t) => t.split(' › ').at(-1).slice(0, 50))).length);
}
const known = flakes.filter((x) => x.specs.length).length; const top3 = ['observation.spec.js', 'observation-rulings.spec.js', 'dispatch-presets.spec.js'].reduce((s, k) => s + (bySpec[k]?.length || 0), 0);
console.log('flakes with a known spec', known, '; top three', pct(top3, known), '; failed-test count among logged flakes', tally(flakes.filter((x) => x.log), (x) => x.nFailed));
const dp = bySpec['dispatch-presets.spec.js'] || [];
console.log('dispatch-presets flakes with net::ERR_ABORTED', dp.filter((x) => x.errors.some((e) => /ERR_ABORTED/.test(e))).length, 'of', dp.length);
const specsAt = execFileSync('git', ['ls-tree', '-r', '--name-only', 'fe541ee9', 'tests/e2e'], { encoding: 'utf8' }).split('\n').filter((f) => /\.spec\.[jt]s$/.test(f)).length;
console.log('specs at fe541ee9', specsAt, '-> others', specsAt - Object.keys(bySpec).length);

h('Cost');
const pr = census.filter((x) => x.event === 'pull_request'); const prFl = pr.filter((x) => x.class === 'flake');
console.log('PR E2E-red attempts', pr.length, tally(pr, (x) => x.class), '; flakes', prFl.length, 'in', new Set(prFl.map((x) => x.runId)).size, 'runs;', pct(prFl.length, pr.length));
const det = (id, a) => { const p = join(dir, 'detail', `LinearViewer-${id}-${a}.json`); return existsSync(p) ? J(p) : null; };
const jm = (jobs) => jobs.filter((j) => j.started_at && j.completed_at).reduce((s, j) => s + mins(j.started_at, j.completed_at), 0);
let wallRed = 0; let wallRerun = 0; let e2eRed = 0; let e2eRedCopied = 0; let jobsRedNew = 0; let jobsRerunNew = 0;
for (const x of flakes) {
  const d = det(x.runId, x.attempt); const prev = det(x.runId, x.attempt - 1); const next = x.rerun ? det(x.runId, x.attempt + 1) : null;
  const prevKeys = new Set((prev?.jobs || []).map((j) => `${j.name}@${j.started_at}`));
  wallRed += mins(d.startedAt, d.updatedAt); e2eRed += jm(d.jobs.filter((j) => /^E2E/.test(j.name)));
  e2eRedCopied += jm(d.jobs.filter((j) => /^E2E/.test(j.name) && prevKeys.has(`${j.name}@${j.started_at}`)));
  jobsRedNew += jm(d.jobs.filter((j) => !prevKeys.has(`${j.name}@${j.started_at}`)));
  if (next) {
    wallRerun += mins(next.startedAt, next.updatedAt);
    const keys = new Set(d.jobs.map((j) => `${j.name}@${j.started_at}`));
    jobsRerunNew += jm(next.jobs.filter((j) => !keys.has(`${j.name}@${j.started_at}`)));
  }
}
console.log(`wall-clock: red ${wallRed.toFixed(0)} + re-runs ${wallRerun.toFixed(0)} = ${(wallRed + wallRerun).toFixed(0)} min = ${((wallRed + wallRerun) / 60).toFixed(2)} h`);
console.log(`E2E job-minutes in red attempts ${e2eRed.toFixed(0)} (of which ${e2eRedCopied.toFixed(0)} are jobs carried over unchanged from an earlier attempt)`);
console.log(`runner job-minutes actually executed: red attempts ${jobsRedNew.toFixed(0)} + re-run attempts ${jobsRerunNew.toFixed(0)} = ${((jobsRedNew + jobsRerunNew) / 60).toFixed(1)} h`);
const react = flakes.map((x) => x.reactionMinutes).filter((v) => v != null);
console.log('re-run attempts after a flake', flakes.filter((x) => x.rerun).length, 'of all LV re-run attempts', lv.reduce((s, r) => s + r.run_attempt - 1, 0), '; reaction median', median(react).toFixed(2), 'n', react.length);

h('Green-run sample (raw green/*.json)');
const green = readDir('green');
const pop = lv.filter((r) => r.conclusion === 'success' && r.created_at >= '2026-07-03');
const want = new Set(pop.filter((_, i) => i % 8 === 0).map((r) => r.id));
console.log('green pop since 3 Jul', pop.length, 'every 8th', want.size, 'files', green.length, 'match', green.every((g) => want.has(g.runId)) && green.length === want.size);
let logs = 0; let withFl = 0; let flTests = 0; let lbRuns = 0; let lbTests = 0; const bySpecG = {}; const mon = {};
const LB = /reduced motion renders the livebar/;
for (const g of green) {
  const e2e = g.jobs.filter((j) => /^E2E/.test(j.name)); logs += e2e.filter((j) => j.log).length;
  const fl = e2e.flatMap((j) => j.flaky || []); flTests += fl.length; if (fl.length) withFl++;
  const lb = fl.filter((f) => LB.test(f.title)).length; lbTests += lb; if (lb) lbRuns++;
  for (const f of fl) bySpecG[f.file.replace('tests/e2e/', '')] = (bySpecG[f.file.replace('tests/e2e/', '')] || 0) + 1;
  const m = (mon[g.createdAt.slice(0, 7)] ||= { runs: 0, other: 0, lb: 0 }); m.runs++; if (fl.some((f) => !LB.test(f.title))) m.other++; if (lb) m.lb++;
}
const n = green.length;
console.log('runs', n, 'shard logs', logs, '; any retry', pct(withFl, n), `±${ci95(withFl / n, n).toFixed(1)} pts`, '; flaky tests', flTests);
console.log('livebar tests', lbTests, 'in runs', pct(lbRuns, n), `±${ci95(lbRuns / n, n).toFixed(1)} pts`, '; by spec', bySpecG);
for (const [k, v] of Object.entries(mon).sort()) console.log(`  ${k}: other-retry ${pct(v.other, v.runs)}, livebar ${pct(v.lb, v.runs)} (±${ci95(v.lb / v.runs, v.runs).toFixed(0)} pts)`);
const cfg = execFileSync('git', ['show', 'fe541ee9:playwright.config.js'], { encoding: 'utf8' });
console.log('playwright.config.js@fe541ee9', cfg.split('\n').map((l, i) => `${i + 1}: ${l.trim()}`).filter((l) => /retries|workers:|trace:/.test(l)));

h('Masking');
const push = census.filter((x) => x.event === 'push');
console.log('push E2E-red', push.length, tally(push, (x) => x.class));
console.log('PR census rows with an empty prs list', pr.filter((x) => !x.prs.length).length, 'of', pr.length, '(the pushFaults join reads prs)');
const own = A.flakeOnOwnSurface;
console.log('flakes on own surface', own.length, 'attempt rows;', new Set(own.map((x) => x.runId)).size, 'distinct runs', tally(own, (x) => census.find((y) => y.runId === x.runId).event));
const codes = existsSync(join(dir, 'blind-codes.json')) ? J(join(dir, 'blind-codes.json')) : [];
const mc = A.maskingCandidates;
console.log('masking candidates', mc.length, 'attempts in', new Set(mc.map((m) => m.runId)).size, 'runs; blind-coded as flake:',
  codes.filter((c) => c.class === 'flake' && mc.some((m) => c.id.startsWith(`${m.runId}-`))).map((c) => c.id),
  '; all blind real->flake', codes.filter((c) => c.class === 'flake' && census.find((x) => `${x.runId}-${x.attempt}` === c.id)?.class === 'real fault').map((c) => c.id));
if (useGh) {
  for (const p of A.pushFaults) {
    if (!p.pr) { console.log(`  ${p.date.slice(0, 10)} ${p.sha}: no PR number in subject`); continue; }
    const br = execFileSync('gh', ['api', `repos/JKershaw/LinearViewer/pulls/${p.pr}`, '--jq', '.head.ref'], { encoding: 'utf8' }).trim();
    const rows = pr.filter((x) => x.branch === br && x.specs.some((s) => p.specs.includes(s)));
    console.log(`  push ${p.date.slice(0, 10)} ${p.class} PR#${p.pr} (${br}): red PR attempts on the same spec`, rows.map((x) => `${x.runId}/${x.attempt} ${x.class}`));
  }
}
